<section class="section book-detail"><div class="cover cover-<?=($book['id']%5)+1?> large-cover"><span><?=Security::e($book['title'])?></span><i>ARCHON</i></div><div><p class="eyebrow">EBOOK · <?=Security::e($book['language'])?></p><h1><?=Security::e($book['title'])?></h1><p class="author-line">by <a href="/authors/<?=Security::e($book['author_slug'])?>"><?=Security::e($book['author_name'])?></a></p><p class="lead"><?=Security::e($book['short_description'])?></p><p class="price">$<?=number_format((float)($book['sale_price']?:$book['price']),2)?> <?php if($book['sale_price']):?><del>$<?=number_format((float)$book['price'],2)?></del><?php endif;?></p><form action="/cart/add" method="post" class="inline-form"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><input type="hidden" name="book_id" value="<?=$book['id']?>"><input type="hidden" name="return_to" value="/ebooks/<?=Security::e($book['slug'])?>"><button class="button">Add to cart</button></form><form action="/wishlist/toggle" method="post" class="inline-form"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><input type="hidden" name="book_id" value="<?=$book['id']?>"><input type="hidden" name="return_to" value="/ebooks/<?=Security::e($book['slug'])?>"><button class="button outline">Save to wishlist</button></form><p class="secure-note">Secure digital delivery after purchase.</p></div></section><section class="section two-col"><article><h2>About the book</h2><p><?=nl2br(Security::e($book['description']))?></p><h2>About <?=Security::e($book['author_name'])?></h2><p><?=Security::e($book['author_bio'])?></p></article><aside class="metadata"><h3>Book details</h3><dl><dt>ISBN</dt><dd><?=Security::e($book['isbn'])?></dd><dt>Publisher</dt><dd>Archon Publishing House</dd><dt>Published</dt><dd><?=date('F Y',strtotime($book['published_at']))?></dd><dt>Pages</dt><dd><?=Security::e((string)$book['page_count'])?></dd><dt>Formats</dt><dd>PDF · EPUB</dd></dl></aside></section><section class="section reviews"><div class="section-heading"><div><p class="eyebrow">READER NOTES</p><h2>Reviews</h2></div><span class="rating-summary"><?=number_format((float)$book['rating'],1)?> / 5</span></div><?php if($reviews):?><div class="review-list"><?php foreach($reviews as $review):?><article><div><b><?=Security::e($review['customer_name'])?></b><span aria-label="<?=Security::e((string)$review['rating'])?> out of 5 stars"><?=str_repeat('★',(int)$review['rating'])?><i><?=str_repeat('★',5-(int)$review['rating'])?></i></span></div><p><?=nl2br(Security::e($review['body']))?></p></article><?php endforeach;?></div><?php else:?><p>No reader notes yet. Be the first verified reader to leave one.</p><?php endif;?><?php if($canReview):?><form class="panel review-form" method="post" action="/ebooks/<?=Security::e($book['slug'])?>/review"><input type="hidden" name="_token" value="<?=Security::csrf()?>"><h3>Leave your reader note</h3><label>Rating<select name="rating" required><option value="">Choose a rating</option><option value="5">5 — Excellent</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Fair</option><option value="1">1 — Poor</option></select></label><label>Your review<textarea name="body" minlength="15" maxlength="2000" rows="5" required></textarea></label><button class="button">Submit for moderation</button></form><?php elseif(!$customer):?><p class="small-note"><a href="/login">Sign in</a> to review a completed purchase.</p><?php endif;?></section><section class="section parchment"><h2>Continue reading</h2><div class="book-grid"><?php foreach($related as $book):require __DIR__.'/../components/book-card.php';endforeach;?></div></section>
